    # Fill the grid using dynamic programming
    for i in range(1, N):
        for j in range(1, N):
            value = grid_values[i][j][2]
            for di, dj in directions:
                ni, nj = i + di, j + dj
                if 0 <= ni < N and 0 <= nj < N:
                    grid[i][j] = max(grid[i][j], grid[ni][nj] + value)

    # Calculate the maximum values from both paths and return their sum
