            neighbors = [(i - di, j - dj) for di, dj in directions if 0 <= i - di < N and 0 <= j - dj < N]
            for ni, nj in neighbors:
                if grid[ni][nj] > grid_values[ni][nj][2]:
                    break
            else:
                max_value1 = max(max_value1, grid[i][j] + value)
            if grid[ni][nj] > grid_values[ni][nj][2]:
                grid[ni][nj] = grid[i][j]

    for i in range(1, N):
        for j in range(1, N):
            value = grid_values[i][j][2]
            neighbors = [(i - di, j - dj) for di, dj in directions if 0 <= i - di < N and 0 <= j - dj < N]
            for ni, nj in neighbors:
