def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    # Create a 2D array to store the results of subproblems
    dp = [[0] * (n + 1) for _ in range(len(items) + 1)]

    # Fill the dp array
    for i in range(1, len(items) + 1):
        price, importance = items[i - 1]
        for j in range(1, n + 1):
            if price <= j:
                dp[i][j] = max(dp[i - 1][j], importance + dp[i - 1][j - price])
            else:
                dp[i][j] = dp[i - 1][j]

    # The maximum total importance value is the result of subproblem (m, n)
    return dp[m][n]
