def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    # Initialize a 2D array dp where dp[i][j] represents the maximum value achievable with at most i time units using first j herbs
    dp = [[0 for _ in range(M + 1)] for _ in range(T + 1)]

    # Iterate through each herb
    for i, (time, value) in enumerate(herbs):
        # Update the dp table for each time value
        for j in range(1, T + 1):
            if j >= time:
                dp[j][i + 1] = max(dp[j][i + 1], dp[j - time][i] + value)
            else:
                dp[j][i + 1] = dp[j][i]

    # The maximum total value achievable with T time units using all herbs is stored in dp[T][M]
    return dp[T][M]
