        pick_value = herbs[i][0] + recursive_max(i + 1, time_left - herbs[i][0])

        # Calculate the value if the herb is not picked
        not_pick_value = recursive_max(i + 1, time_left)

        # Return the maximum value between picking and not picking the herb
        return max(pick_value, not_pick_value)

    # Start the recursive function from the first herb (index 0) and time left (T)
    return recursive_max(0, T)
