def next_permutation(perm: list) -> bool:
    if len(perm) <= 1:
        return False

    for i in range(len(perm) - 2, -1, -1):
        # Find the rightmost element smaller than perm[i]
        for j in range(len(perm) - 1, i, -1):
            if perm[i] < perm[j]:
                # Swap the elements
                perm[i], perm[j] = perm[j], perm[i]
                break
        else:
            # If no such element is found, the permutation is already in descending order
            return False

    # Reverse the order of elements starting from i+1 to the end
    perm[i + 1 :] = perm[i + 1 :][::-1]

    return True
